statements.sql:
CREATE TABLE IF NOT EXISTS workspaces (
  id            TEXT    PRIMARY KEY,
  name          TEXT    NOT NULL DEFAULT '',
  created_at_ms INTEGER NOT NULL,
  updated_at_ms INTEGER NOT NULL,
  is_default    INTEGER NOT NULL DEFAULT 0,
  metadata_json TEXT    NOT NULL DEFAULT '{}'
) STRICT;

CREATE UNIQUE INDEX IF NOT EXISTS workspaces_default ON workspaces(is_default) WHERE is_default = 1;

CREATE TABLE IF NOT EXISTS toolbox_approvals (
  name           TEXT    PRIMARY KEY,
  manifest_sha256 TEXT   NOT NULL,
  image          TEXT    NOT NULL,
  approved_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE IF NOT EXISTS extension_approvals (
  id             TEXT    PRIMARY KEY,
  digest         TEXT    NOT NULL,
  approved_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE IF NOT EXISTS auth_secrets (
  name          TEXT PRIMARY KEY,
  value         TEXT NOT NULL,
  updated_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE IF NOT EXISTS auth_sessions (
  id              TEXT    PRIMARY KEY,
  token_sha256    BLOB    NOT NULL,
  label           TEXT    NOT NULL DEFAULT '',
  created_at_ms   INTEGER NOT NULL,
  expires_at_ms   INTEGER NOT NULL,
  last_seen_at_ms INTEGER NOT NULL
) STRICT;

CREATE INDEX IF NOT EXISTS auth_sessions_expiry ON auth_sessions(expires_at_ms);

CREATE TABLE IF NOT EXISTS auth_throttle (
  scope           TEXT    PRIMARY KEY,
  failures        INTEGER NOT NULL,
  last_failed_ms  INTEGER NOT NULL,
  locked_until_ms INTEGER NOT NULL
) STRICT;

CREATE INDEX IF NOT EXISTS auth_throttle_last_failed ON auth_throttle(last_failed_ms);

CREATE TABLE IF NOT EXISTS notifications (
  id            TEXT    PRIMARY KEY,
  title         TEXT    NOT NULL,
  body          TEXT    NOT NULL DEFAULT '',
  level         TEXT    NOT NULL DEFAULT 'info',
  created_at_ms INTEGER NOT NULL,
  read_at_ms    INTEGER,
  session_key   TEXT,
  job_id        TEXT
) STRICT;

CREATE INDEX IF NOT EXISTS notifications_created ON notifications(created_at_ms DESC, id ASC);
CREATE INDEX IF NOT EXISTS notifications_unread ON notifications(created_at_ms DESC) WHERE read_at_ms IS NULL;
